import{_ as s,o as t,c as a,a3 as l}from"./chunks/framework.CgYN3nbS.js";const m=JSON.parse('{"title":"Lab 04 — Les essais","description":"","frontmatter":{"title":"Lab 04 — Les essais","aside":false},"headers":[],"relativePath":"labs/lab04-essais.md","filePath":"labs/lab04-essais.md"}'),i={name:"labs/lab04-essais.md"};function r(n,e,o,u,c,p){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="lab-04-—-les-essais" tabindex="-1">Lab 04 — Les essais <a class="header-anchor" href="#lab-04-—-les-essais" aria-label="Permalink to &quot;Lab 04 — Les essais&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectifs du laboratoire</strong><br><ul class="list-disc pl-5"><li>Faire le plan d&#39;essai du Lab 03 sur deux ou trois outils, dans les mêmes conditions.</li><li>Documenter chaque résultat avec une mesure et une preuve.</li><li>Résumer les résultats dans un tableau de comparaison et en tirer trois constats, sans recommander.</li></ul></div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Modalités</strong><br><ul class="list-disc pl-5"><li>Avec <strong>votre équipe de la session</strong>, sur la question reçue au tirage.</li><li>Durée : de 20 h à la fin de la soirée, en équipe, après la matière. Vous quittez la réunion du cours pour travailler ensemble; l&#39;enseignant reste disponible dans la réunion du cours si vous avez une question. Ce qui n&#39;est pas terminé se complète avant la séance 5.</li><li>Remise : la fiche remplie, déposée dans l&#39;<strong>équipe Teams du cours</strong>. Travail <strong>formatif</strong>. La fiche deviendra l&#39;annexe A et le cœur de la section 6 de l&#39;évaluation 1.</li></ul></div><hr><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Ce soir, vous ne lisez plus ce que les outils <strong>prétendent</strong> faire : vous vérifiez ce qu&#39;ils <strong>font</strong>. Mélanie ne vous demande pas lequel est le meilleur. Elle vous demande ce que chacun peut faire pour son entreprise, ce qu&#39;il coûte, et ce qui pourrait coincer.</p><blockquote><p><strong>Règle d&#39;or, encore :</strong> on compare, on ne choisit pas. Le choix viendra à l&#39;évaluation 2.</p></blockquote><hr><h2 id="preparation" tabindex="-1">Préparation (10 min) <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation (10 min) {#preparation}&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Ouvrir votre fiche du Lab 03 et relire les commentaires de l&#39;enseignant</span></label></li><li><label><input type="checkbox"><span class="check-text">Corriger les critères « Réussi si… » qui ne passent pas le <a href="./../modules/01-faisabilite/04-essayer-et-comparer#retour-sur-le-lab-03">test des deux observateurs</a></span></label></li><li><label><input type="checkbox"><span class="check-text"><a href="./../fiches/lab04-fiche-essais.docx" download>Télécharger la fiche du Lab 04 (Word)</a> et la placer dans le dossier partagé de l&#39;équipe</span></label></li><li><label><input type="checkbox"><span class="check-text">Créer un dossier <code>captures</code> dans le dossier partagé</span></label></li><li><label><input type="checkbox"><span class="check-text">Vérifier que les comptes d&#39;essai sont ouverts et actifs, et sortir les données inventées</span></label></li><li><label><input type="checkbox"><span class="check-text">Répartir les rôles : qui manipule, qui chronomètre et note, qui fait les captures. On change de rôle à chaque outil.</span></label></li><li><label><input type="checkbox"><span class="check-text">Désigner la personne qui jouera <strong>Mélanie</strong> : celle qui connaît le moins les outils. Elle ne regarde pas les autres essayer avant son tour.</span></label></li></ul><hr><h2 id="partie-1" tabindex="-1">Partie 1 — Les essais (environ 80 min) <a class="header-anchor" href="#partie-1" aria-label="Permalink to &quot;Partie 1 — Les essais (environ 80 min) {#partie-1}&quot;">​</a></h2><p>Faites les essais de votre plan et notez les résultats <strong>directement dans la fiche du Lab 04</strong>, partie 1. Travaillez dans la fiche placée dans le dossier partagé de l&#39;équipe : tout le monde la voit en même temps.</p><p>Pour chaque essai et chaque outil, écrivez dans la case :</p><ul><li>le <strong>résultat</strong> : réussi, échoué ou non vérifiable;</li><li>la <strong>mesure</strong> brute : un temps, un nombre de clics, un poids, un score;</li><li>ce que vous avez <strong>observé</strong> : un imprévu, une aide demandée, ou la raison du « non vérifiable ».</li></ul><p>Pour le temps, utilisez le chronomètre d&#39;un téléphone. Nommez les captures au fur et à mesure : <code>Q1-Outil-E3-01.png</code> (question, outil, essai, numéro).</p><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Gérer le temps</strong><ul class="list-disc pl-5"><li>Trois outils et sept essais, c&#39;est 21 essais : environ <strong>4 minutes chacun</strong>. Gardez le rythme.</li><li>Faites les essais <strong>dans le même ordre</strong> pour chaque outil.</li><li>Si le temps manque, faites <strong>tous les essais sur deux outils</strong> plutôt que la moitié des essais sur trois. Un tableau à trous ne compare rien.</li><li>Un essai bloqué depuis 5 minutes ? Notez ce qui bloque, marquez-le « échoué » ou « non vérifiable » selon le cas, et passez au suivant.</li></ul></div><p>Pour chaque outil, notez aussi une seule fois dans la fiche : <strong>la date</strong>, <strong>le forfait d&#39;essai</strong> utilisé, <strong>l&#39;appareil et le navigateur</strong>.</p><hr><h2 id="partie-2" tabindex="-1">Partie 2 — Le tableau de comparaison (15 min) <a class="header-anchor" href="#partie-2" aria-label="Permalink to &quot;Partie 2 — Le tableau de comparaison (15 min) {#partie-2}&quot;">​</a></h2><p>C&#39;est la version de travail du tableau demandé dans la section 6 de l&#39;évaluation 1. Remplissez-le dans la fiche, une colonne par outil.</p><p>Ce soir, remplissez les lignes que vos essais permettent de remplir. La ligne marquée <strong>(maison)</strong> se complète après le cours, avec la section <a href="./../modules/01-faisabilite/04-essayer-et-comparer#a-faire-a-la-maison">À faire à la maison</a> présentée à la fin de la matière.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ligne</th><th style="text-align:left;">Ce qu&#39;on y écrit</th><th style="text-align:left;">Appuyé sur</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Famille de solution</strong></td><td style="text-align:left;">Service spécialisé, fonction de la plateforme ou développement sur mesure</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>Ce que l&#39;outil fait</strong></td><td style="text-align:left;">Les besoins essentiels du Lab 03 couverts, et ceux qui ne le sont pas</td><td style="text-align:left;">Vos essais (E1, E2…)</td></tr><tr><td style="text-align:left;"><strong>Modèle de prix</strong></td><td style="text-align:left;">Au mois, à l&#39;utilisateur, à la transaction, avec plafond…</td><td style="text-align:left;">Page de prix, avec la date</td></tr><tr><td style="text-align:left;"><strong>Coût estimé sur trois ans</strong> (maison)</td><td style="text-align:left;">En dollars canadiens, avec le calcul</td><td style="text-align:left;">Vos hypothèses, écrites sous le tableau</td></tr><tr><td style="text-align:left;"><strong>Temps pour apprendre</strong></td><td style="text-align:left;">Le temps mesuré pour la personne qui jouait Mélanie, et l&#39;aide en français</td><td style="text-align:left;">Vos essais</td></tr><tr><td style="text-align:left;"><strong>Points à vérifier</strong></td><td style="text-align:left;">Ce qui est resté non vérifiable, et comment le vérifier</td><td style="text-align:left;">Vos essais</td></tr></tbody></table><div class="hors-rapport"><strong>Aucune case ne juge</strong><br> Pas de « bon », « excellent », « ★★★★ » ni de note sur 10. Chaque case contient un fait : une mesure, un prix, un format, une date. Pas de colonne « gagnant » non plus. </div><hr><h2 id="partie-3" tabindex="-1">Partie 3 — Trois constats (10 min) <a class="header-anchor" href="#partie-3" aria-label="Permalink to &quot;Partie 3 — Trois constats (10 min) {#partie-3}&quot;">​</a></h2><p>Écrivez dans la fiche <strong>trois constats</strong> sur votre question, comme ceux de l&#39;<a href="./../modules/01-faisabilite/04-essayer-et-comparer#activite-1">activité 1</a>.</p><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Chaque constat renvoie à un essai (E1, E2…) ou à une source datée</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins un constat porte sur une <strong>limite</strong> ou un <strong>échec</strong></span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins un constat touche une contrainte du mandat : Viator, Square, le réseau au quai, la Loi 25, la langue, le budget annuel…</span></label></li><li><label><input type="checkbox"><span class="check-text">Aucun « nous recommandons », « il faudrait », « le meilleur », « à privilégier »</span></label></li></ul><hr><h2 id="retour" tabindex="-1">Partie 4 — Préparer le retour en grand groupe (5 min) <a class="header-anchor" href="#retour" aria-label="Permalink to &quot;Partie 4 — Préparer le retour en grand groupe (5 min) {#retour}&quot;">​</a></h2><p>Le retour en grand groupe a lieu <strong>au début de la séance 5</strong>. L&#39;enseignant désigne alors une équipe par question : toutes les équipes se préparent. Notez dans la fiche ce que vous direz en <strong>2 minutes</strong>, sans diapositive :</p><ol><li>Les outils essayés, avec leur famille.</li><li>Deux de vos constats, dont au moins une limite.</li><li>Ce qui est resté non vérifiable.</li></ol><hr><h2 id="remise" tabindex="-1">Remise <a class="header-anchor" href="#remise" aria-label="Permalink to &quot;Remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le tableau des résultats rempli, avec une mesure pour chaque essai fait</span></label></li><li><label><input type="checkbox"><span class="check-text">Les changements au plan et les imprévus, expliqués</span></label></li><li><label><input type="checkbox"><span class="check-text">Au moins une capture par outil collée dans la fiche; les autres rangées dans le dossier <code>captures</code>, bien nommées</span></label></li><li><label><input type="checkbox"><span class="check-text">Le tableau de comparaison rempli, y compris la ligne faite à la maison, avec les hypothèses du coût sur trois ans</span></label></li><li><label><input type="checkbox"><span class="check-text">Trois constats appuyés, sans recommandation</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé <code>lab04-equipeN-QX.docx</code> et déposé dans l&#39;équipe Teams du cours</span></label></li></ul><hr><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><p>Dans l&#39;<strong>évaluation 1</strong>, votre fiche devient :</p><ul><li>l&#39;<strong>annexe A</strong> (le plan, les mesures, les captures);</li><li>le <strong>tableau de comparaison</strong> et les <strong>résultats résumés</strong> de votre question, dans la section 6;</li><li>une partie des <strong>problèmes à prévoir et des questions au client</strong> (section 7), grâce à vos « non vérifiables ».</li></ul><p>À la <strong>séance 5 (28 octobre)</strong>, on commence par le retour en grand groupe sur les cinq questions. On travaille ensuite l&#39;organisation du rapport et l&#39;écriture pour une cliente qui n&#39;est pas du métier. Apportez votre brouillon.</p>',40)])])}const b=s(i,[["render",r]]);export{m as __pageData,b as default};
